function showUpcomingFeatures(){
 const feature=upcomingFeatures[view],content=document.querySelector('#content');
 if(!feature||!content)return;
 const notice=document.createElement('aside');notice.className='coming-soon-notice';notice.setAttribute('aria-label','Coming soon');
 notice.innerHTML='<span class="coming-soon-label">Coming soon</span><div><strong>'+esc(feature[0])+'</strong><p>'+esc(feature[1])+'</p></div>';
 content.prepend(notice);
}
