 const series=finance?Array.from({length:6},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-5+i);const key=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');return {label:d.toLocaleDateString('en-IN',{month:'short'}),value:state.fees.filter(f=>!f.void_reason&&f.payment_date.startsWith(key)).reduce((n,f)=>n+f.amount,0)/100};}):[...new Set((state.attendanceSummary||[]).map(r=>r.date))].sort().slice(-6).map(day=>({label:new Date(day+'T12:00:00Z').toLocaleDateString('en-IN',{day:'numeric',month:'short'}),value:(state.attendanceSummary||[]).find(r=>r.date===day&&r.status==='Present')?.count||0}));
 const maximum=Math.max(...series.map(x=>x.value),1),chart=document.querySelector('#overview-chart');
