  admissions:{title:'Admission application',fields:[F('name','Student full name'),F('guardian','Parent / guardian'),F('phone','Parent phone','tel'),classField,F('applied_on','Application date','date'),S('status','Application status',['Inquiry','Interview','Accepted','Declined'].map(v=>[v,v])),F('notes','Application notes','textarea',false,{max:2000})],defaults:{status:'Inquiry',applied_on:today()}},
