  expenses:{title:'Record expense',fields:[S('category','Category',['Salaries','Utilities','Supplies','Maintenance','Transport','Other'].map(v=>[v,v])),F('payee','Paid to'),F('description','Description'),F('amount','Amount paid (₹)','money'),F('payment_date','Payment date','date'),S('method','Payment method',['Cash','UPI','Bank transfer','Card','Cheque'].map(v=>[v,v])),F('reference','Payment reference','text',false)],defaults:{payment_date:today()},note:'Record money already paid. Saved financial entries remain in the ledger.'},
  exams:{title:'Assessment details',fields:[F('name','Assessment name'),classField,F('subject','Subject'),F('exam_date','Assessment date','date'),F('max_marks','Maximum marks','number',true,{min:1,max:1000}),S('status','Result status',[['Scheduled','Scheduled / marks entry open'],['Published','Published / marks locked']])],defaults:{exam_date:today(),max_marks:100,status:'Scheduled'},note:'Enter all students’ marks before publishing. Reopen a published exam to correct marks.'},
