  books:{title:'Library book',fields:[F('title','Book title'),F('isbn','ISBN / accession number'),F('author','Author'),F('category','Category'),F('copies','Total copies','number',true,{min:0,max:10000})],defaults:{copies:1}},
  loans:{title:'Issue a library book',fields:[S('book_id','Book',optionsOf((state.books||[]).filter(b=>b.available>0),'title')),S('student_id','Student',students),F('issued_on','Issue date','date'),F('due_on','Return due date','date')],defaults:{issued_on:today(),due_on:new Date(Date.now()+14*86400000).toISOString().slice(0,10)}},
  routes:{title:'Transport route',fields:[F('name','Route name'),F('vehicle','Vehicle registration'),F('driver','Driver name'),F('phone','Driver phone','tel'),F('capacity','Passenger seats','number',true,{min:1,max:100}),F('monthly_fee','Monthly fee (₹)','money',true,{min:0}),F('stops','Stops (one per line)','textarea',true,{max:2000})],defaults:{capacity:30,monthly_fee:0}},
