  products:{title:'School supply item',fields:[F('name','Item name'),F('sku','Item code'),F('price','Price per item (₹)','money',true,{min:0}),F('stock','Quantity in stock','number',true,{min:0}),S('active','Item status',[['true','Active'],['false','Archived']])],defaults:{active:true,price:0,stock:0}},
