  homework:{title:'Homework assignment',fields:[classField,F('subject','Subject'),F('title','Assignment title'),F('instructions','Instructions','textarea',true,{max:12000}),F('due_on','Due date','date'),F('max_marks','Maximum score','number',true,{min:1,max:1000})],defaults:{due_on:today(),max_marks:20}},
  leave:{title:'Request leave',fields:[...(has('portal:read')?[S('student_id','Student',students)]:has('leave:review')?[S('student_id','Leave for',[['','Myself (staff leave)'],...students],false)]:[]),F('from_date','From date','date'),F('to_date','To date','date'),F('reason','Reason','textarea',true,{max:2000})],defaults:{from_date:today(),to_date:today()},note:'Approval does not automatically change the attendance register. The class teacher records daily attendance.'}
