function fieldMarkup(f){
 const attrs=(f.required?' required':'')+' name="'+f.name+'"';
 const control=f.type==='select'?'<select'+attrs+'>'+f.options.map(([value,label])=>'<option value="'+esc(value)+'">'+esc(label)+'</option>').join('')+'</select>':f.type==='textarea'?'<textarea'+attrs+' rows="4" maxlength="'+(f.max||2000)+'"></textarea>':'<input'+attrs+' type="'+(f.type==='money'?'number':f.type)+'"'+(['money','number'].includes(f.type)?' min="'+(f.min??(f.type==='money'?0.01:0))+'" max="'+(f.max??1000000)+'" step="'+(f.type==='money'?'0.01':'1')+'"':f.type==='text'?' maxlength="'+(f.max||160)+'"':'')+'>';
 return '<label class="'+(f.type==='textarea'?'span-two':'')+'">'+esc(f.label)+(f.required?'<span class="required-star" aria-hidden="true"> *</span>':'')+control+'</label>';
}
function getRecord(kind,id){return ({customers:state.customers,classes:state.classes,staff:state.staff,admissions:state.admissions,invoices:state.invoices,expenses:state.expenses,exams:state.exams,timetable:state.timetable,books:state.books,routes:state.routes,transport:state.transport,notices:state.notices,products:state.products,payroll:state.payroll,homework:state.homework})[kind]?.find(r=>r.id===id);}
function openSchoolForm(kind,id=0,initial={}){
 const def=formDefinition(kind);if(!def)return;
 const existing=id?getRecord(kind,id):null,values={...def.defaults,...existing,...initial},modal=document.querySelector('#modal');
 modal.innerHTML='<form><div class="dialog-title"><span class="eyebrow">'+(id?'EDIT RECORD':'NEW RECORD')+'</span><h2>'+def.title+'</h2></div>'+(def.note?'<p>'+esc(def.note)+'</p>':'')+'<div class="form-grid">'+def.fields.map(fieldMarkup).join('')+'</div><div class="error" role="alert"></div><div class="formactions"><button type="button" class="secondary" id="cancel">Cancel</button><button type="submit">'+(id?'Save changes':'Save record')+'</button></div></form>';
 const form=modal.querySelector('form');
 for(const f of def.fields){const input=form.elements[f.name];if(values[f.name]!==undefined&&values[f.name]!==null)input.value=f.type==='money'?Number(values[f.name])/100:f.name==='active'?String(!!values[f.name]):values[f.name];}
 if(kind==='classes'&&id)form.elements.name.readOnly=true;
 if(kind==='payroll'){
  const fillSalary=()=>{const staff=state.staff.find(s=>s.id===Number(form.elements.staff_id.value));form.elements.basic.value=((staff?.base_salary||0)/100).toFixed(2);};
  form.elements.staff_id.onchange=fillSalary;if(!id)fillSalary();
 }
 if(kind==='transport'){
  const fillStops=()=>{const route=(state.routes||[]).find(r=>r.id===Number(form.elements.route_id.value));form.elements.stop.innerHTML=(route?.stops||'').split('\n').filter(Boolean).map(s=>'<option>'+esc(s.trim())+'</option>').join('');};
  form.elements.route_id.onchange=fillStops;fillStops();if(values.stop)form.elements.stop.value=values.stop;
 }
 form.querySelector('#cancel').onclick=()=>modal.close();
 form.onsubmit=async e=>{e.preventDefault();authBusy(form);try{
  const d=Object.fromEntries(new FormData(form));
  for(const f of def.fields){if(f.type==='money')d[f.name]=Math.round(Number(d[f.name])*100);else if(f.type==='number'||f.name.endsWith('_id'))d[f.name]=d[f.name]?Number(d[f.name]):null;else if(f.name==='active')d.active=d.active==='true';}
  await api(kind+(id?'/'+id:''),id?'PATCH':'POST',d);state=await api('state');if(!form.isConnected)return;modal.close();render();toast('Record saved.');
 }catch(err){if(form.isConnected)authError(form,err.message);}};
 modal.showModal();
}
function schoolFeeForm(invoiceId=0){
 if(!activeStudents().length)return toast('Add an active student first.');
 const invoice=(state.invoices||[]).find(i=>i.id===invoiceId),modal=document.querySelector('#modal'),requestId=crypto.randomUUID();
 modal.innerHTML='<form><h2>Record a fee payment</h2><p>Record money already received. Payments linked to an invoice reduce its outstanding balance.</p><div class="form-grid"><label>Student<select name="student_id">'+studentOptions()+'</select></label><label>Fee invoice<select name="invoice_id"><option value="">Other payment / no invoice</option></select></label>'+field('Payment for','purpose','text','required maxlength="160"')+field('Amount received (₹)','amount','number','required min="0.01" max="1000000" step="0.01"')+field('Payment date','payment_date','date','required value="'+today()+'" max="'+today()+'"')+'<label>Payment method<select name="method">'+['Cash','UPI','Bank transfer','Card','Cheque'].map(m=>'<option>'+m+'</option>').join('')+'</select></label></div><div class="error" role="alert"></div><div class="formactions"><button type="button" class="secondary" id="cancel">Cancel</button><button type="submit">Save payment</button></div></form>';
 const form=modal.querySelector('form');if(invoice)form.elements.student_id.value=invoice.student_id;
 const fillInvoices=()=>{form.elements.invoice_id.innerHTML='<option value="">Other payment / no invoice</option>'+(state.invoices||[]).filter(i=>i.student_id===Number(form.elements.student_id.value)&&i.status==='Open'&&i.balance>0).map(i=>'<option value="'+i.id+'">INV-'+String(i.id).padStart(4,'0')+' · '+esc(i.purpose)+' · '+money(i.balance)+' due</option>').join('');};
 const fillAmount=()=>{const selected=(state.invoices||[]).find(i=>i.id===Number(form.elements.invoice_id.value));if(selected){form.elements.purpose.value=selected.purpose;form.elements.amount.value=(selected.balance/100).toFixed(2);}form.elements.amount.max=selected?(selected.balance/100).toFixed(2):'1000000';};
 form.elements.student_id.onchange=()=>{fillInvoices();fillAmount();form.elements.purpose.value='';form.elements.amount.value='';};form.elements.invoice_id.onchange=fillAmount;fillInvoices();if(invoice){form.elements.invoice_id.value=invoiceId;fillAmount();}
 form.querySelector('#cancel').onclick=()=>modal.close();form.onsubmit=async e=>{e.preventDefault();authBusy(form);try{const d=Object.fromEntries(new FormData(form));d.student_id=Number(d.student_id);d.invoice_id=d.invoice_id?Number(d.invoice_id):null;d.amount=Math.round(Number(d.amount)*100);d.request_id=requestId;await api('fees','POST',d);state=await api('state');if(!form.isConnected)return;modal.close();render();toast('Payment saved. You can print the receipt from Fee payments.');}catch(err){if(form.isConnected)authError(form,err.message);}};modal.showModal();
}
function actionDialog(title,description,fields,perform,button='Confirm'){
 const modal=document.querySelector('#modal');modal.innerHTML='<form><h2>'+esc(title)+'</h2><p>'+esc(description)+'</p>'+fields+'<div class="error" role="alert"></div><div class="formactions"><button type="button" class="secondary" id="action-cancel">Cancel</button><button type="submit">'+esc(button)+'</button></div></form>';
 const form=modal.querySelector('form');form.querySelector('#action-cancel').onclick=()=>modal.close();form.onsubmit=async e=>{e.preventDefault();authBusy(form);try{await perform(Object.fromEntries(new FormData(form)));state=await api('state');if(!form.isConnected)return;modal.close();render();toast('Changes saved.');}catch(err){if(form.isConnected)authError(form,err.message);}};modal.showModal();
}
function bindActions(){
 document.querySelectorAll('[data-action]').forEach(button=>button.onclick=()=>{
  const id=Number(button.dataset.id),kind=button.dataset.kind;
  switch(button.dataset.action){
   case 'edit':return openSchoolForm(kind,id);
   case 'student':return studentProfile(id);
   case 'pay':return schoolFeeForm(id);
   case 'invoice':return printInvoice(id);
   case 'marks':return marksForm(id);
   case 'results':return resultSheet(id);
   case 'new-loan':return openSchoolForm('loans');
   case 'issue':return openSchoolForm('loans',0,{book_id:id});
   case 'new-transport':return openSchoolForm('transport');
   case 'assign':return openSchoolForm('transport',0,{route_id:id});
   case 'enroll':return actionDialog('Enrol applicant','This creates an active student record and retains the admission application.',field('New admission number','admission_no','text','required maxlength="40"'),d=>api('admissions/'+id+'/enroll','POST',d),'Enrol student');
   case 'void':return actionDialog('Void fee receipt','This keeps the receipt in the audit trail and reopens any linked invoice balance.',field('Reason for voiding','reason','text','required maxlength="500"'),d=>api('fees/'+id+'/void','POST',d),'Void receipt');
   case 'cancel-invoice':return actionDialog('Cancel invoice','The invoice stays in the records but no longer counts as money owed.','',()=>api('invoices/'+id+'/cancel','POST',{}),'Cancel invoice');
   case 'return':return actionDialog('Return library book','Confirm that the school has received this copy back.','',()=>api('loans/'+id+'/return','POST',{}),'Return book');
   case 'remove-transport':return actionDialog('Remove transport allocation','This frees a seat on the route.','',()=>api('transport/'+id,'DELETE',{}),'Remove allocation');
   case 'remove-period':return actionDialog('Remove timetable period','This removes the lesson from the class timetable.','',()=>api('timetable/'+id,'DELETE',{}),'Remove period');
   case 'payslip':return payslip(id);
   case 'pay-salary':return actionDialog('Record salary payment','Confirm that the net salary has been paid. This adds one linked salary expense to the ledger.',field('Payment date','paid_on','date','required value="'+today()+'"')+'<label>Payment method<select name="method"><option>Bank transfer</option><option>UPI</option><option>Cash</option><option>Cheque</option></select></label>'+field('Payment reference','reference','text','required maxlength="100"'),d=>api('payroll/'+id+'/pay','POST',d),'Record salary payment');
   case 'submissions':return homeworkSubmissions(id);
   case 'grade':return gradeSubmission(id,Number(button.dataset.student));
   case 'review-leave':return actionDialog('Review leave request','Choose an outcome and add a note for the applicant.','<label>Decision<select name="status"><option>Approved</option><option>Declined</option></select></label>'+field('Review note','review_note','text','maxlength="2000"'),d=>api('leave/'+id+'/review','POST',d),'Save decision');
   case 'generate-payroll':return actionDialog('Generate monthly payroll','Creates draft salaries from each active staff member’s monthly basic salary. Existing salary records are kept.',field('Salary month','month','month','required value="'+today().slice(0,7)+'"'),async d=>{const result=await api('payroll/generate','POST',d);toast(result.count+' draft salary records generated.');},'Generate drafts');
  }
 });
}
function showPrintable(html){const modal=document.querySelector('#modal');modal.innerHTML='<article class="receipt">'+html+'</article><div class="formactions"><button class="secondary" id="print-close">Close</button><button id="print-document">Print / Save PDF</button></div>';modal.querySelector('#print-close').onclick=()=>modal.close();modal.querySelector('#print-document').onclick=()=>window.print();modal.showModal();}
function printHeader(label){return '<div class="eyebrow">'+esc(label)+'</div><h2>'+esc(schoolLabel())+'</h2><p>'+esc(state.settings?.school_address||'')+'<br>'+esc(state.settings?.school_phone||'')+'</p><hr>';}
function printInvoice(id){const i=state.invoices.find(i=>i.id===id);if(!i)return;showPrintable(printHeader('FEE INVOICE')+'<h3>INV-'+String(i.id).padStart(4,'0')+'</h3><p>Student: <strong>'+esc(i.student)+'</strong><br>Admission: '+esc(i.admission_no)+' · Class: '+esc(i.class_name)+'</p><p>'+esc(i.purpose)+'<br>Academic year: '+esc(i.academic_year)+'<br>Due date: '+dateLabel(i.due_date)+'</p>'+table(['Invoice amount','Received','Outstanding'],['<tr><td>'+money(i.amount)+'</td><td>'+money(i.paid)+'</td><td>'+money(i.status==='Cancelled'?0:i.balance)+'</td></tr>'])+'<p>Status: '+invoiceStatus(i)+'</p>');}
function studentProfile(id){
 const s=state.customers.find(s=>s.id===id);if(!s)return;
 const invoices=(state.invoices||[]).filter(i=>i.student_id===id&&i.status==='Open'),marks=(state.marks||[]).filter(m=>m.student_id===id),route=(state.transport||[]).find(a=>a.student_id===id);
 showPrintable(printHeader('STUDENT PROFILE')+'<div class="profile-title"><span class="profile-avatar">'+esc(s.name.split(' ').map(x=>x[0]).slice(0,2).join(''))+'</span><div><h2>'+esc(s.name)+'</h2><p>'+esc(s.admission_no)+' · Class '+esc(s.class_name)+' · '+esc(s.status||'Active')+'</p></div></div><div class="profile-grid"><div><small>Parent / guardian</small><strong>'+esc(s.guardian||'—')+'</strong></div><div><small>Contact</small><strong>'+esc(s.phone||'—')+'</strong><span>'+esc(s.email)+'</span></div><div><small>Date of birth</small><strong>'+dateLabel(s.dob)+'</strong></div><div><small>Admitted on</small><strong>'+dateLabel(s.admitted_on)+'</strong></div><div><small>Home address</small><strong>'+esc(s.address||'—')+'</strong></div><div><small>Transport</small><strong>'+esc(route?route.route+' · '+route.stop:'Not assigned')+'</strong></div></div>'+(has('fees:read')?'<h3>Fee account</h3><p>Total outstanding: <strong>'+money(invoices.reduce((sum,i)=>sum+i.balance,0))+'</strong></p>':'')+(marks.length?'<h3>Assessment record</h3>'+table(['Assessment','Subject','Marks'],marks.map(m=>{const exam=state.exams.find(e=>e.id===m.exam_id);return exam?'<tr><td>'+esc(exam.name)+'</td><td>'+esc(exam.subject)+'</td><td>'+m.marks+' / '+exam.max_marks+'</td></tr>':''})):''));
 if(has('students:write')){const b=document.createElement('button');b.className='secondary';b.textContent='Edit student';b.onclick=()=>{document.querySelector('#modal').close();openSchoolForm('customers',id);};document.querySelector('#modal .formactions').prepend(b);}
}
function marksForm(id){
 const exam=state.exams.find(e=>e.id===id);if(exam.status==='Published')return toast('Reopen the exam before editing marks.');
 const students=activeStudents().filter(s=>s.class_name===exam.class_name),modal=document.querySelector('#modal');
 modal.innerHTML='<form><h2>Enter assessment marks</h2><p>'+esc(exam.name)+' · '+esc(exam.subject)+' · Class '+esc(exam.class_name)+' · Maximum '+exam.max_marks+'</p>'+table(['Student','Marks','Teacher remarks'],students.map(s=>{const m=state.marks.find(m=>m.exam_id===id&&m.student_id===s.id);return '<tr><td>'+esc(s.name)+'</td><td><input type="number" name="mark-'+s.id+'" min="0" max="'+exam.max_marks+'" step="1" value="'+(m?.marks??'')+'" aria-label="Marks for '+esc(s.name)+'"></td><td><input name="remark-'+s.id+'" maxlength="300" value="'+esc(m?.remarks||'')+'" aria-label="Remarks for '+esc(s.name)+'"></td></tr>';}),'No students in this class.')+'<p class="muted">Blank marks are left unchanged. Enter marks for every student before publishing.</p><div class="error" role="alert"></div><div class="formactions"><button type="button" class="secondary" id="marks-cancel">Cancel</button><button type="submit">Save marks</button></div></form>';
 const form=modal.querySelector('form');form.querySelector('#marks-cancel').onclick=()=>modal.close();form.onsubmit=async e=>{e.preventDefault();authBusy(form);try{const marks=students.filter(s=>form.elements['mark-'+s.id].value!=='').map(s=>({student_id:s.id,marks:Number(form.elements['mark-'+s.id].value),remarks:form.elements['remark-'+s.id].value}));await api('exams/'+id+'/marks','POST',{marks});state=await api('state');modal.close();render();toast('Marks saved.');}catch(err){if(form.isConnected)authError(form,err.message);}};modal.showModal();
}
function resultSheet(id){const exam=state.exams.find(e=>e.id===id),marks=state.marks.filter(m=>m.exam_id===id);showPrintable(printHeader('ASSESSMENT RESULT SHEET')+'<h3>'+esc(exam.name)+' · '+esc(exam.subject)+'</h3><p>Class '+esc(exam.class_name)+' · '+dateLabel(exam.exam_date)+' · '+exam.status+'</p>'+table(['Student','Marks','Percentage','Grade','Remarks'],marks.map(m=>{const student=state.customers.find(s=>s.id===m.student_id),p=m.marks/exam.max_marks*100;return '<tr><td>'+esc(student?.name||'Student')+'</td><td>'+m.marks+' / '+exam.max_marks+'</td><td>'+p.toFixed(1)+'%</td><td>'+(p>=90?'A+':p>=80?'A':p>=70?'B+':p>=60?'B':p>=50?'C':p>=33?'D':'E')+'</td><td>'+esc(m.remarks)+'</td></tr>';}),'No marks entered yet.')+'<p>Principal: '+esc(state.settings?.principal||'')+'</p>');}
function settingsPage(){
 const fields=[formField('school_name','School name'),formField('principal','Principal name'),formField('school_email','School email','email'),formField('school_phone','Office phone','tel'),formField('academic_year','Academic year'),formField('school_address','School address','textarea',true,{max:500})];
 document.querySelector('#content').innerHTML='<div class="settings-layout"><div class="panel"><div class="panelhead"><div><h2>School profile</h2><p>Used in reports, invoices, and school documents</p></div></div><form id="settings-form"><div class="form-grid">'+fields.map(fieldMarkup).join('')+'</div><div class="error" role="alert"></div><div class="formactions"><button type="submit">Save school details</button></div></form></div><div><div class="panel"><h2>Data backup</h2><p class="settings-note">Create a consistent database snapshot while the app is running. Backups include school records and staff authentication data.</p><button class="secondary" id="create-backup">Create database backup</button><p id="backup-result" role="status" class="muted"></p></div><div class="panel"><h2>Sample school</h2><p class="settings-note">Explore the modules with fictional students, staff, invoices, attendance, exams, books, and routes.</p>'+(state.settings.demo_seed?badge('Sample data loaded on '+dateLabel(state.settings.demo_seed)):'<button class="secondary" id="seed-demo">Load sample data</button><p class="muted">Available only while the school has no operational records.</p>')+'</div><div class="panel"><h2>Access management</h2><p class="settings-note">Add staff accounts, issue password links, and manage role permissions.</p><button class="secondary" id="settings-users">Manage staff access →</button></div></div></div>';
 const form=document.querySelector('#settings-form');for(const f of fields)form.elements[f.name].value=state.settings[f.name]||'';
 form.onsubmit=async e=>{e.preventDefault();authBusy(form);try{await api('settings','PATCH',Object.fromEntries(new FormData(form)));state=await api('state');render();toast('School details updated.');}catch(err){if(form.isConnected)authError(form,err.message);}};
 document.querySelector('#settings-users').onclick=()=>goTo('users');
 document.querySelector('#seed-demo')?.addEventListener('click',()=>actionDialog('Load sample school','Fictional records will be added to this empty school. Staff accounts and passwords are preserved.','',()=>api('demo','POST',{}),'Load sample data'));
 document.querySelector('#create-backup').onclick=async e=>{e.currentTarget.disabled=true;try{const result=await api('backups','POST',{});document.querySelector('#backup-result').textContent='Backup saved in the school data/backups folder: '+result.filename;}catch(err){toast(err.message);}finally{const b=document.querySelector('#create-backup');if(b)b.disabled=false;}};
}
function reportsPage(){
 const start=today().slice(0,7)+'-01';
 document.querySelector('#content').innerHTML='<div class="panel report-controls"><label>From<input type="date" id="report-from" value="'+start+'"></label><label>To<input type="date" id="report-to" value="'+today()+'"></label><label>Class<select id="report-class"><option value="">All classes</option>'+(state.classes||[]).map(c=>'<option>'+esc(c.name)+'</option>').join('')+'</select></label><button class="secondary" id="report-print">Print report</button></div><div id="report-content"></div>';
 const draw=()=>{
  const from=document.querySelector('#report-from').value,to=document.querySelector('#report-to').value,className=document.querySelector('#report-class').value,target=document.querySelector('#report-content');
  if(!from||!to||from>to){target.innerHTML='<div class="panel">Choose a valid date range.</div>';return;}
  const payments=state.fees.filter(f=>!f.void_reason&&f.payment_date>=from&&f.payment_date<=to&&(!className||f.class_name===className)),collected=payments.reduce((sum,f)=>sum+f.amount,0),expenses=(state.expenses||[]).filter(e=>e.payment_date>=from&&e.payment_date<=to),spent=expenses.reduce((sum,e)=>sum+e.amount,0),invoices=(state.invoices||[]).filter(i=>i.status==='Open'&&i.balance>0&&(!className||i.class_name===className)),attendance=(state.attendanceByClass||[]).filter(a=>a.date>=from&&a.date<=to&&(!className||a.class_name===className));
  const dates=[...new Set(attendance.map(a=>a.date))].sort().reverse(),attendanceRows=dates.map(date=>{const rows=attendance.filter(a=>a.date===date),count=status=>rows.filter(a=>a.status===status).reduce((sum,a)=>sum+a.count,0),total=rows.reduce((sum,a)=>sum+a.count,0);return [date,count('Present'),count('Absent'),count('On leave'),total,total?(count('Present')/total*100).toFixed(1)+'%':'—'];});
  target.innerHTML='<div class="cards">'+(has('fees:read')?'<div class="card"><small>Collections in period</small><div class="number">'+money(collected)+'</div></div><div class="card"><small>School-wide expenses in period</small><div class="number">'+money(spent)+'</div></div><div class="card"><small>Current outstanding balance</small><div class="number">'+money(invoices.reduce((sum,i)=>sum+i.balance,0))+'</div></div>':'')+'<div class="card"><small>Students in current register</small><div class="number">'+activeStudents().filter(s=>!className||s.class_name===className).length+'</div></div></div>'+(has('attendance:read')?'<div class="panel"><div class="panelhead"><div><h2>Attendance register</h2><p>'+dateLabel(from)+' to '+dateLabel(to)+'</p></div><button class="secondary" id="export-attendance">Export attendance</button></div>'+table(['Date','Present','Absent','On leave','Marked','Present %'],attendanceRows.map(row=>'<tr>'+row.map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>'),'No attendance recorded in this period.')+'</div>':'')+(has('fees:read')?'<div class="panel"><div class="panelhead"><h2>Payment ledger</h2><button class="secondary" id="export-payments">Export collections</button></div>'+table(['Receipt','Student','Date','Method','Amount'],payments.map(f=>'<tr><td>FEE-'+String(f.id).padStart(4,'0')+'</td><td>'+esc(f.student)+'</td><td>'+dateLabel(f.payment_date)+'</td><td>'+esc(f.method)+'</td><td>'+money(f.amount)+'</td></tr>'),'No payments recorded in this period.')+'</div><div class="panel"><div class="panelhead"><h2>Current fee dues</h2><button class="secondary" id="export-dues">Export outstanding fees</button></div>'+table(['Student','Class','Invoice','Due','Balance'],invoices.map(i=>'<tr><td>'+esc(i.student)+'</td><td>'+esc(i.class_name)+'</td><td>INV-'+String(i.id).padStart(4,'0')+'</td><td>'+dateLabel(i.due_date)+'</td><td>'+money(i.balance)+'</td></tr>'),'No outstanding invoices.')+'</div>':'');
  document.querySelector('#export-attendance')?.addEventListener('click',()=>downloadCSV('attendance-report.csv',['Date','Present','Absent','On leave','Marked','Present %'],attendanceRows));
  document.querySelector('#export-payments')?.addEventListener('click',()=>downloadCSV('payment-ledger.csv',['Receipt','Student','Class','Date','Method','Amount INR'],payments.map(f=>[f.id,f.student,f.class_name,f.payment_date,f.method,f.amount/100])));
  document.querySelector('#export-dues')?.addEventListener('click',()=>downloadCSV('outstanding-fees.csv',['Student','Class','Invoice','Due date','Balance INR'],invoices.map(i=>[i.student,i.class_name,i.id,i.due_date,i.balance/100])));
 };
 ['report-from','report-to','report-class'].forEach(id=>document.querySelector('#'+id).onchange=draw);
 document.querySelector('#report-print').onclick=()=>{const copy=document.querySelector('#report-content').cloneNode(true);copy.querySelectorAll('button').forEach(b=>b.remove());showPrintable(printHeader('SCHOOL MANAGEMENT REPORT')+copy.innerHTML);};draw();
}
